PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT,status TEXT DEFAULT 'active',created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT,is_admin INTEGER DEFAULT 0,created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,email TEXT UNIQUE,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,department_id INTEGER NULL,role_id INTEGER NOT NULL,status TEXT DEFAULT 'active',must_change_password INTEGER DEFAULT 0,last_login_at TEXT NULL,created_at TEXT,updated_at TEXT,FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS permissions (id INTEGER PRIMARY KEY AUTOINCREMENT,key TEXT UNIQUE NOT NULL,label TEXT NOT NULL,description TEXT);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL,permission_id INTEGER NOT NULL,PRIMARY KEY(role_id, permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS programs (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,description TEXT,icon TEXT,status TEXT DEFAULT 'active',created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS categories (id INTEGER PRIMARY KEY AUTOINCREMENT,program_id INTEGER NOT NULL,parent_id INTEGER NULL,name TEXT NOT NULL,description TEXT,sort_order INTEGER DEFAULT 0,status TEXT DEFAULT 'active',created_at TEXT,updated_at TEXT,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE CASCADE,FOREIGN KEY(parent_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS videos (id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT NOT NULL,description TEXT,program_id INTEGER NOT NULL,category_id INTEGER NULL,video_type TEXT DEFAULT 'upload',video_path TEXT NULL,video_url TEXT NULL,thumbnail_path TEXT NULL,duration TEXT NULL,visibility_type TEXT DEFAULT 'all',sort_order INTEGER DEFAULT 0,status TEXT DEFAULT 'draft',created_by INTEGER NOT NULL,created_at TEXT,updated_at TEXT,FOREIGN KEY(program_id) REFERENCES programs(id),FOREIGN KEY(category_id) REFERENCES categories(id),FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS video_departments (video_id INTEGER NOT NULL,department_id INTEGER NOT NULL,PRIMARY KEY(video_id, department_id),FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_roles (video_id INTEGER NOT NULL,role_id INTEGER NOT NULL,PRIMARY KEY(video_id, role_id),FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE,FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_users (video_id INTEGER NOT NULL,user_id INTEGER NOT NULL,PRIMARY KEY(video_id, user_id),FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_progress (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,video_id INTEGER NOT NULL,progress_percent INTEGER DEFAULT 0,completed INTEGER DEFAULT 0,last_watched_at TEXT,created_at TEXT,updated_at TEXT,UNIQUE(user_id, video_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_favorites (user_id INTEGER NOT NULL,video_id INTEGER NOT NULL,created_at TEXT,PRIMARY KEY(user_id, video_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS video_comments (id INTEGER PRIMARY KEY AUTOINCREMENT,video_id INTEGER NOT NULL,user_id INTEGER NOT NULL,comment TEXT NOT NULL,status TEXT DEFAULT 'pending',created_at TEXT,updated_at TEXT,FOREIGN KEY(video_id) REFERENCES videos(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS activity_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NULL,action TEXT NOT NULL,entity_type TEXT NULL,entity_id INTEGER NULL,ip_address TEXT,user_agent TEXT,created_at TEXT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
